import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`mna-activity`,heroTitle:`Track M&A activity in minutes`,heroSubtitle:`Perplexity Computer monitors deal announcements, summarizes transaction terms, and builds your deal log automatically.`,inputUrlCta:`Track this sector`,inputUrlPlaceholder:`e.g. fintech, healthcare, semiconductors...`,inputUrlPrefill:`Go to {url} to understand the sector I want to track. Then monitor M&A deal announcements from Bloomberg, SEC filings (EDGAR), and PR Newswire for this sector in real time. For each transaction: 1) Summarize the acquirer, target, deal value, and structure. 2) Extract the strategic rationale and any stated synergies. 3) Note the advisors, financing details, and expected close date. 4) Add each deal to a running M&A deal log organized by date. 5) Compile a weekly digest summarizing new deals, updated deal statuses, and sector trends.`,heroOverlaySteps:[`Identifying your target sector and key subsegments to monitor`,`Scanning Bloomberg, SEC EDGAR, and PR Newswire for recent deal announcements`,`Extracting transaction terms, rationale, and advisor details for each deal`,`Deal log populated and weekly digest configured — ready to review`],generatingSteps:[`Visiting {url} to identify your sector focus and key companies to watch`,`Designing an agent to monitor Bloomberg, SEC filings, and PR Newswire for deal activity`,`Configuring transaction parsing for deal terms, synergies, and strategic rationale`,`Setting up a running deal log and automated weekly digest delivery`],featureSectionTitle:`From sector to deal intelligence`,featureCardTitles:[`Connects to your tool stack`,`Outputs you can brief from`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Slack, Email — Computer plugs into your tools so deal monitoring and reporting happen in one workflow.`,`Running deal logs. Transaction summaries. Weekly sector digests. Advisor and financing breakdowns. Computer delivers work you can share with your team or drop into a pitch deck.`],capabilitySectionTitle:`Your deal desk, on autopilot`,capabilitySectionSubtitle:`Name your sector, step away, come back to a complete M&A briefing.`,capabilityCards:[{title:`Deal Monitoring`,description:`Computer can scan Bloomberg, SEC filings, and PR Newswire around the clock — surfacing new deal announcements the moment they drop.`},{title:`Transaction Summaries`,description:`Computer can extract deal value, structure, advisors, financing, and strategic rationale — and format each summary for quick review.`},{title:`Weekly Digests`,description:`Computer can compile new deals, status updates, and sector trend analysis into a concise weekly report — delivered to your inbox or Slack.`},{title:`Connect Your Tools`,description:`Computer can read and write to Google Sheets, Slack, Notion, Email, and more — build workflows across your entire research stack.`},{title:`Remember & Learn`,description:`Computer can remember your sector focus, deal size thresholds, and priority targets across sessions — so every scan builds on what came before.`},{title:`Monitor & Alert`,description:`Computer can watch for deals matching specific criteria — acquirer, target size, geography — and ping you the moment a relevant announcement hits.`}]});export{t as default};
